def profile(record):
    fields = PUBLIC_FIELDS
    display_name = record["display_name"].replace(ZERO_WIDTH_SPACE, " ")
    display_name = " ".join(display_name.split())
    if not display_name:
        # Legacy CSV imports carry their own column list.
        fields = record.get("columns", fields)
    public = {field: record[field] for field in fields}
    public["display_name"] = display_name or record["customer_id"]
    return public
